1	import { useState } from "react";
2	import { Sparkles, Loader2, CheckCircle2, Briefcase, TrendingUp } from "lucide-react";
3	import {
4	  Dialog,
5	  DialogContent,
6	  DialogHeader,
7	  DialogTitle,
8	  DialogDescription,
9	} from "@/components/ui/dialog";
10	import { Button } from "@/components/ui/button";
11	import { Badge } from "@/components/ui/badge";
12	import { Skeleton } from "@/components/ui/skeleton";
13	import { useRediscoveredCandidates, useImportRediscovered } from "@/hooks/useRediscovery";
14	import type { RediscoveredCandidate } from "@/hooks/useRediscovery";
15	
16	// ─── Similarity badge colour ──────────────────────────────────────────────────
17	
18	function similarityVariant(pct: number): "default" | "secondary" | "outline" {
19	  if (pct >= 80) return "default";
20	  if (pct >= 70) return "secondary";
21	  return "outline";
22	}
23	
24	// ─── Candidate row ────────────────────────────────────────────────────────────
25	
26	interface CandidateItemProps {
27	  candidate: RediscoveredCandidate;
28	  selected: boolean;
29	  imported: boolean;
30	  onToggle: (id: string) => void;
31	}
32	
33	function CandidateItem({ candidate, selected, imported, onToggle }: CandidateItemProps) {
34	  return (
35	    <div
36	      className={`flex items-center gap-3 rounded-lg border p-3 cursor-pointer transition-colors ${
37	        imported
38	          ? "border-border bg-muted/30 opacity-60 cursor-not-allowed"
39	          : selected
40	          ? "border-primary/60 bg-primary/5"
41	          : "border-border hover:border-primary/30 hover:bg-muted/30"
42	      }`}
43	      onClick={() => !imported && onToggle(candidate.resume_id)}
44	      role="checkbox"
45	      aria-checked={selected}
46	      aria-disabled={imported}
47	      tabIndex={imported ? -1 : 0}
48	      onKeyDown={(e) => {
49	        if (!imported && (e.key === " " || e.key === "Enter")) {
50	          e.preventDefault();
51	          onToggle(candidate.resume_id);
52	        }
53	      }}
54	    >
55	      {/* Checkbox indicator */}
56	      <div
57	        className={`h-4 w-4 shrink-0 rounded border flex items-center justify-center transition-colors ${
58	          imported
59	            ? "border-muted bg-muted"
60	            : selected
61	            ? "border-primary bg-primary"
62	            : "border-muted-foreground/40"
63	        }`}
64	        aria-hidden="true"
65	      >
66	        {(selected || imported) && (
67	          <CheckCircle2 className={`h-3 w-3 ${imported ? "text-muted-foreground" : "text-primary-foreground"}`} />
68	        )}
69	      </div>
70	
71	      {/* Info */}
72	      <div className="flex-1 min-w-0">
73	        <p className="text-sm font-medium truncate">
74	          {candidate.candidate_name}
75	          {imported && (
76	            <span className="ml-2 text-xs text-muted-foreground font-normal">
77	              (already imported)
78	            </span>
79	          )}
80	        </p>
81	        <div className="flex items-center gap-1.5 mt-0.5 flex-wrap">
82	          <Briefcase className="h-3 w-3 text-muted-foreground shrink-0" />
83	          <span className="text-xs text-muted-foreground truncate max-w-[180px]">
84	            {candidate.original_job_title}
85	          </span>
86	          {candidate.overall_score_on_original_job !== null && (
87	            <>
88	              <span className="text-muted-foreground text-xs">·</span>
89	              <TrendingUp className="h-3 w-3 text-muted-foreground shrink-0" />
90	              <span className="text-xs text-muted-foreground">
91	                {candidate.overall_score_on_original_job}% on original
92	              </span>
93	            </>
94	          )}
95	        </div>
96	      </div>
97	
98	      {/* Similarity badge */}
99	      <Badge
100	        variant={similarityVariant(candidate.similarity)}
101	        className="shrink-0 text-xs font-semibold tabular-nums"
102	        aria-label={`${candidate.similarity}% similarity to current job`}
103	      >
104	        {candidate.similarity}% match
105	      </Badge>
106	    </div>
107	  );
108	}
109	
110	// ─── Skeleton loading state ───────────────────────────────────────────────────
111	
112	function RediscoverySkeletonList() {
113	  return (
114	    <div className="space-y-2">
115	      {[1, 2, 3].map((i) => (
116	        <div key={i} className="flex items-center gap-3 rounded-lg border border-border p-3">
117	          <Skeleton className="h-4 w-4 rounded shrink-0" />
118	          <div className="flex-1 space-y-1.5">
119	            <Skeleton className="h-4 w-40" />
120	            <Skeleton className="h-3 w-56" />
121	          </div>
122	          <Skeleton className="h-5 w-20 rounded-full" />
123	        </div>
124	      ))}
125	    </div>
126	  );
127	}
128	
129	// ─── Main dialog ──────────────────────────────────────────────────────────────
130	
131	interface RediscoveryDialogProps {
132	  open: boolean;
133	  onOpenChange: (open: boolean) => void;
134	  jobId: string;
135	  /** IDs of resumes already in this job (to show as already-imported) */
136	  existingResumePaths?: Set<string>;
137	}
138	
139	const RediscoveryDialog = ({
140	  open,
141	  onOpenChange,
142	  jobId,
143	  existingResumePaths,
144	}: RediscoveryDialogProps) => {
145	  const { data: candidates, isLoading, error } = useRediscoveredCandidates(open ? jobId : null);
146	  const { mutate: importCandidates, isPending: isImporting } = useImportRediscovered(jobId);
147	
148	  const [selected, setSelected] = useState<Set<string>>(new Set());
149	
150	  const toggleCandidate = (resumeId: string) => {
151	    setSelected((prev) => {
152	      const next = new Set(prev);
153	      if (next.has(resumeId)) next.delete(resumeId);
154	      else next.add(resumeId);
155	      return next;
156	    });
157	  };
158	
159	  const handleImport = () => {
160	    if (selected.size === 0) return;
161	    importCandidates([...selected], {
162	      onSuccess: () => {
163	        setSelected(new Set());
164	        onOpenChange(false);
165	      },
166	    });
167	  };
168	
169	  const handleOpenChange = (nextOpen: boolean) => {
170	    if (!nextOpen) setSelected(new Set());
171	    onOpenChange(nextOpen);
172	  };
173	
174	  const count = candidates?.length ?? 0;
175	
176	  return (
177	    <Dialog open={open} onOpenChange={handleOpenChange}>
178	      <DialogContent className="sm:max-w-[560px] max-h-[90vh] flex flex-col">
179	        <DialogHeader>
180	          <DialogTitle className="flex items-center gap-2">
181	            <Sparkles className="h-4 w-4 text-primary" />
182	            Rediscovered Candidates
183	          </DialogTitle>
184	          <DialogDescription>
185	            {isLoading
186	              ? "Searching your talent history…"
187	              : count > 0
188	              ? `${count} past candidate${count !== 1 ? "s" : ""} match this role based on JD similarity. Select any to import and re-rank.`
189	              : "No matching candidates found in your talent history."}
190	          </DialogDescription>
191	        </DialogHeader>
192	
193	        {/* Candidate list */}
194	        <div className="flex-1 overflow-y-auto space-y-2 py-1 min-h-0">
195	          {isLoading && <RediscoverySkeletonList />}
196	
197	          {!isLoading && error && (
198	            <div className="text-sm text-destructive text-center py-6">
199	              Failed to load candidates. Please try again.
200	            </div>
201	          )}
202	
203	          {!isLoading && !error && count === 0 && (
204	            <div className="text-sm text-muted-foreground text-center py-8">
205	              No past candidates match this job description yet.
206	              <br />
207	              As you rank more candidates, they will appear here automatically.
208	            </div>
209	          )}
210	
211	          {!isLoading && candidates && candidates.map((candidate) => {
212	            const alreadyImported = Boolean(
213	              existingResumePaths?.has(candidate.resume_id),
214	            );
215	            return (
216	              <CandidateItem
217	                key={candidate.resume_id}
218	                candidate={candidate}
219	                selected={selected.has(candidate.resume_id)}
220	                imported={alreadyImported}
221	                onToggle={toggleCandidate}
222	              />
223	            );
224	          })}
225	        </div>
226	
227	        {/* Footer */}
228	        {count > 0 && (
229	          <div className="flex items-center justify-between gap-3 pt-3 border-t border-border">
230	            <p className="text-xs text-muted-foreground">
231	              {selected.size > 0
232	                ? `${selected.size} candidate${selected.size !== 1 ? "s" : ""} selected`
233	                : "Select candidates to import"}
234	            </p>
235	            <div className="flex items-center gap-2">
236	              <Button
237	                variant="outline"
238	                size="sm"
239	                onClick={() => handleOpenChange(false)}
240	                disabled={isImporting}
241	              >
242	                Cancel
243	              </Button>
244	              <Button
245	                size="sm"
246	                onClick={handleImport}
247	                disabled={selected.size === 0 || isImporting}
248	                className="gap-1.5"
249	              >
250	                {isImporting ? (
251	                  <>
252	                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
253	                    Importing…
254	                  </>
255	                ) : (
256	                  <>
257	                    Import {selected.size > 0 ? selected.size : ""} candidate{selected.size !== 1 ? "s" : ""}
258	                  </>
259	                )}
260	              </Button>
261	            </div>
262	          </div>
263	        )}
264	      </DialogContent>
265	    </Dialog>
266	  );
267	};
268	
269	export default RediscoveryDialog;
