1	import "jsr:@supabase/functions-js/edge-runtime.d.ts";
2	import { createClient } from "jsr:@supabase/supabase-js@2";
3	
4	const corsHeaders = {
5	  "Access-Control-Allow-Origin": "*",
6	  "Access-Control-Allow-Headers":
7	    "authorization, x-client-info, apikey, content-type",
8	};
9	
10	Deno.serve(async (req) => {
11	  if (req.method === "OPTIONS") {
12	    return new Response("ok", { headers: corsHeaders });
13	  }
14	
15	  try {
16	    // ── Auth ──────────────────────────────────────────────────────────────────
17	    const authHeader = req.headers.get("Authorization");
18	    if (!authHeader) {
19	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
20	        status: 401,
21	        headers: { ...corsHeaders, "Content-Type": "application/json" },
22	      });
23	    }
24	
25	    const supabase = createClient(
26	      Deno.env.get("SUPABASE_URL")!,
27	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
28	    );
29	
30	    const token = authHeader.replace("Bearer ", "");
31	    const {
32	      data: { user },
33	      error: authError,
34	    } = await supabase.auth.getUser(token);
35	
36	    if (authError || !user) {
37	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
38	        status: 401,
39	        headers: { ...corsHeaders, "Content-Type": "application/json" },
40	      });
41	    }
42	
43	    // ── Validate input ────────────────────────────────────────────────────────
44	    const body = await req.json() as {
45	      job_id?: string;
46	      source_resume_ids?: string[];
47	    };
48	
49	    const { job_id, source_resume_ids } = body;
50	
51	    if (!job_id || typeof job_id !== "string") {
52	      return new Response(JSON.stringify({ error: "job_id is required" }), {
53	        status: 400,
54	        headers: { ...corsHeaders, "Content-Type": "application/json" },
55	      });
56	    }
57	
58	    if (
59	      !source_resume_ids ||
60	      !Array.isArray(source_resume_ids) ||
61	      source_resume_ids.length === 0
62	    ) {
63	      return new Response(
64	        JSON.stringify({ error: "source_resume_ids must be a non-empty array" }),
65	        {
66	          status: 400,
67	          headers: { ...corsHeaders, "Content-Type": "application/json" },
68	        },
69	      );
70	    }
71	
72	    if (source_resume_ids.length > 20) {
73	      return new Response(
74	        JSON.stringify({ error: "Cannot import more than 20 resumes at once" }),
75	        {
76	          status: 400,
77	          headers: { ...corsHeaders, "Content-Type": "application/json" },
78	        },
79	      );
80	    }
81	
82	    // ── Verify target job ownership ───────────────────────────────────────────
83	    const { data: targetJob, error: targetJobError } = await supabase
84	      .from("jobs")
85	      .select("id, user_id, status")
86	      .eq("id", job_id)
87	      .single();
88	
89	    if (targetJobError || !targetJob) {
90	      return new Response(JSON.stringify({ error: "Target job not found" }), {
91	        status: 404,
92	        headers: { ...corsHeaders, "Content-Type": "application/json" },
93	      });
94	    }
95	
96	    if (targetJob.user_id !== user.id) {
97	      return new Response(JSON.stringify({ error: "Forbidden" }), {
98	        status: 403,
99	        headers: { ...corsHeaders, "Content-Type": "application/json" },
100	      });
101	    }
102	
103	    // ── Fetch source resumes (verify ownership via jobs join) ─────────────────
104	    const { data: sourceResumes, error: sourceError } = await supabase
105	      .from("resumes")
106	      .select(
107	        "id, job_id, filename, file_path, candidate_name, parsed_json, parsed_text, embedding, status",
108	      )
109	      .in("id", source_resume_ids)
110	      .eq("status", "done");
111	
112	    if (sourceError) {
113	      console.error("Failed to fetch source resumes:", sourceError);
114	      throw new Error("Failed to fetch source resumes");
115	    }
116	
117	    if (!sourceResumes || sourceResumes.length === 0) {
118	      return new Response(
119	        JSON.stringify({ error: "No valid source resumes found" }),
120	        {
121	          status: 404,
122	          headers: { ...corsHeaders, "Content-Type": "application/json" },
123	        },
124	      );
125	    }
126	
127	    // Verify all source resumes belong to the same user (via their original job)
128	    const sourceJobIds = [...new Set(sourceResumes.map((r: { job_id: string }) => r.job_id))];
129	    const { data: sourceJobs, error: sourceJobsError } = await supabase
130	      .from("jobs")
131	      .select("id, user_id")
132	      .in("id", sourceJobIds);
133	
134	    if (sourceJobsError) throw new Error("Failed to verify source job ownership");
135	
136	    const unauthorizedJobs = (sourceJobs ?? []).filter(
137	      (j: { id: string; user_id: string }) => j.user_id !== user.id,
138	    );
139	    if (unauthorizedJobs.length > 0) {
140	      return new Response(JSON.stringify({ error: "Forbidden: some resumes do not belong to you" }), {
141	        status: 403,
142	        headers: { ...corsHeaders, "Content-Type": "application/json" },
143	      });
144	    }
145	
146	    // ── Check for already-imported resumes (avoid duplicates) ─────────────────
147	    const { data: existingResumes } = await supabase
148	      .from("resumes")
149	      .select("file_path")
150	      .eq("job_id", job_id);
151	
152	    const existingFilePaths = new Set(
153	      (existingResumes ?? []).map((r: { file_path: string }) => r.file_path),
154	    );
155	
156	    type SourceResume = {
157	      id: string;
158	      job_id: string;
159	      filename: string;
160	      file_path: string;
161	      candidate_name: string | null;
162	      parsed_json: unknown;
163	      parsed_text: string | null;
164	      embedding: unknown;
165	      status: string;
166	    };
167	
168	    const toImport = (sourceResumes as SourceResume[]).filter(
169	      (r) => !existingFilePaths.has(r.file_path),
170	    );
171	
172	    if (toImport.length === 0) {
173	      return new Response(
174	        JSON.stringify({
175	          imported: [],
176	          skipped: source_resume_ids.length,
177	          message: "All selected candidates are already in this job",
178	        }),
179	        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
180	      );
181	    }
182	
183	    // ── Insert cloned resume rows ─────────────────────────────────────────────
184	    const newRows = toImport.map((r) => ({
185	      job_id: job_id,
186	      filename: r.filename,
187	      file_path: r.file_path,
188	      candidate_name: r.candidate_name,
189	      parsed_json: r.parsed_json,
190	      parsed_text: r.parsed_text,
191	      embedding: r.embedding,
192	      status: "done", // already parsed — ready for ranking
193	    }));
194	
195	    const { data: inserted, error: insertError } = await supabase
196	      .from("resumes")
197	      .insert(newRows)
198	      .select("id, filename, candidate_name");
199	
200	    if (insertError) {
201	      console.error("Failed to insert cloned resumes:", insertError);
202	      throw new Error("Failed to import resumes");
203	    }
204	
205	    const importedIds = (inserted ?? []).map((r: { id: string }) => r.id);
206	    const skippedCount = sourceResumes.length - toImport.length;
207	
208	    // ── Trigger ranking for the imported resumes ──────────────────────────────
209	    // Fire-and-forget: rank the new resume rows against the target job.
210	    // We call rank-resumes but only for the newly imported resume IDs.
211	    // This is async — we don't wait for it to complete.
212	    if (importedIds.length > 0) {
213	      const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
214	      const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
215	
216	      // Trigger via internal HTTP (fire-and-forget)
217	      fetch(`${supabaseUrl}/functions/v1/rank-resumes`, {
218	        method: "POST",
219	        headers: {
220	          "Authorization": `Bearer ${serviceKey}`,
221	          "Content-Type": "application/json",
222	        },
223	        body: JSON.stringify({
224	          job_id: job_id,
225	          resume_ids: importedIds,
226	        }),
227	      }).catch((err) => {
228	        console.error("Failed to trigger ranking for imported resumes:", err);
229	      });
230	    }
231	
232	    return new Response(
233	      JSON.stringify({
234	        imported: inserted ?? [],
235	        skipped: skippedCount,
236	        message: `${importedIds.length} candidate${importedIds.length !== 1 ? "s" : ""} imported. Ranking in progress.`,
237	      }),
238	      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
239	    );
240	  } catch (error: unknown) {
241	    const message = error instanceof Error ? error.message : "Unknown error";
242	    console.error("import-rediscovered error:", message);
243	    return new Response(JSON.stringify({ error: message }), {
244	      status: 500,
245	      headers: { ...corsHeaders, "Content-Type": "application/json" },
246	    });
247	  }
248	});
