1	import "jsr:@supabase/functions-js/edge-runtime.d.ts";
2	import { createClient } from "jsr:@supabase/supabase-js@2";
3	
4	const corsHeaders = {
5	  "Access-Control-Allow-Origin": "*",
6	  "Access-Control-Allow-Headers":
7	    "authorization, x-client-info, apikey, content-type",
8	};
9	
10	const MATCH_THRESHOLD = 0.65;
11	const MATCH_COUNT = 20;
12	
13	Deno.serve(async (req) => {
14	  if (req.method === "OPTIONS") {
15	    return new Response("ok", { headers: corsHeaders });
16	  }
17	
18	  try {
19	    // ── Auth ──────────────────────────────────────────────────────────────────
20	    const authHeader = req.headers.get("Authorization");
21	    if (!authHeader) {
22	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
23	        status: 401,
24	        headers: { ...corsHeaders, "Content-Type": "application/json" },
25	      });
26	    }
27	
28	    const supabase = createClient(
29	      Deno.env.get("SUPABASE_URL")!,
30	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
31	    );
32	
33	    const token = authHeader.replace("Bearer ", "");
34	    const {
35	      data: { user },
36	      error: authError,
37	    } = await supabase.auth.getUser(token);
38	
39	    if (authError || !user) {
40	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
41	        status: 401,
42	        headers: { ...corsHeaders, "Content-Type": "application/json" },
43	      });
44	    }
45	
46	    // ── Validate input ────────────────────────────────────────────────────────
47	    const body = await req.json() as { job_id?: string };
48	    const { job_id } = body;
49	
50	    if (!job_id || typeof job_id !== "string") {
51	      return new Response(JSON.stringify({ error: "job_id is required" }), {
52	        status: 400,
53	        headers: { ...corsHeaders, "Content-Type": "application/json" },
54	      });
55	    }
56	
57	    // ── Verify job ownership + fetch jd_embedding ─────────────────────────────
58	    const { data: job, error: jobError } = await supabase
59	      .from("jobs")
60	      .select("id, user_id, title, jd_embedding")
61	      .eq("id", job_id)
62	      .single();
63	
64	    if (jobError || !job) {
65	      return new Response(JSON.stringify({ error: "Job not found" }), {
66	        status: 404,
67	        headers: { ...corsHeaders, "Content-Type": "application/json" },
68	      });
69	    }
70	
71	    if (job.user_id !== user.id) {
72	      return new Response(JSON.stringify({ error: "Forbidden" }), {
73	        status: 403,
74	        headers: { ...corsHeaders, "Content-Type": "application/json" },
75	      });
76	    }
77	
78	    if (!job.jd_embedding) {
79	      // JD embedding not yet computed — return empty (feature not ready for this job)
80	      return new Response(
81	        JSON.stringify({ rediscovered: [], message: "JD embedding not available yet" }),
82	        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
83	      );
84	    }
85	
86	    // ── pgvector similarity search via RPC ────────────────────────────────────
87	    const { data: similarResumes, error: rpcError } = await supabase.rpc(
88	      "find_similar_resumes",
89	      {
90	        target_embedding: job.jd_embedding,
91	        owner_id: user.id,
92	        exclude_job_id: job_id,
93	        match_threshold: MATCH_THRESHOLD,
94	        match_count: MATCH_COUNT,
95	      },
96	    );
97	
98	    if (rpcError) {
99	      console.error("find_similar_resumes RPC error:", rpcError);
100	      throw new Error("Similarity search failed");
101	    }
102	
103	    if (!similarResumes || similarResumes.length === 0) {
104	      return new Response(
105	        JSON.stringify({ rediscovered: [] }),
106	        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
107	      );
108	    }
109	
110	    // ── Enrich with original job titles ──────────────────────────────────────
111	    const jobIds = [...new Set((similarResumes as Array<{ job_id: string }>).map((r) => r.job_id))];
112	
113	    const { data: originalJobs, error: jobsError } = await supabase
114	      .from("jobs")
115	      .select("id, title")
116	      .in("id", jobIds)
117	      .eq("user_id", user.id); // double-check ownership
118	
119	    if (jobsError) {
120	      console.error("Failed to fetch original job titles:", jobsError);
121	    }
122	
123	    const jobTitleMap = new Map<string, string>(
124	      (originalJobs ?? []).map((j: { id: string; title: string }) => [j.id, j.title]),
125	    );
126	
127	    // ── Build response ────────────────────────────────────────────────────────
128	    type SimilarResume = {
129	      resume_id: string;
130	      job_id: string;
131	      candidate_name: string | null;
132	      filename: string;
133	      similarity: number;
