1	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
2	import { supabase } from "@/integrations/supabase/client";
3	import { toast } from "sonner";
4	
5	// ─── Types ────────────────────────────────────────────────────────────────────
6	
7	export interface RediscoveredCandidate {
8	  resume_id: string;
9	  candidate_name: string;
10	  filename: string;
11	  /** Similarity to current job's JD, 0–100 */
12	  similarity: number;
13	  original_job_id: string;
14	  original_job_title: string;
15	  /** Overall score from original job ranking, or null if not yet ranked */
16	  overall_score_on_original_job: number | null;
17	}
18	
19	interface RediscoverResponse {
20	  rediscovered: RediscoveredCandidate[];
21	  message?: string;
22	}
23	
24	interface ImportResponse {
25	  imported: Array<{ id: string; filename: string; candidate_name: string | null }>;
26	  skipped: number;
27	  message: string;
28	}
29	
30	// ─── Hook: useRediscoveredCandidates ────────────────────────────────────────
31	
32	/**
33	 * Fetches past candidates whose embeddings are similar to the current job's JD embedding.
34	 * Only runs when:
35	 *   - user is authenticated
36	 *   - a jobId is provided
37	 * Returns empty array (not loading) when disabled.
38	 */
39	export function useRediscoveredCandidates(jobId: string | null) {
40	  return useQuery<RediscoveredCandidate[]>({
41	    queryKey: ["rediscovery", jobId],
42	    queryFn: async (): Promise<RediscoveredCandidate[]> => {
43	      if (!jobId) return [];
44	
45	      const { data, error } = await supabase.functions.invoke<RediscoverResponse>(
46	        "rediscover-candidates",
47	        { body: { job_id: jobId } },
48	      );
49	
50	      if (error) throw error;
51	      return data?.rediscovered ?? [];
52	    },
53	    enabled: !!jobId,
54	    staleTime: 5 * 60 * 1000, // 5 minutes — similarity results don't change often
55	    retry: 1,
56	  });
57	}
58	
59	// ─── Hook: useImportRediscovered ────────────────────────────────────────────
60	
61	/**
62	 * Imports selected past-candidate resumes into the current job and triggers ranking.
63	 * Invalidates the job's resumes and results query keys after success.
64	 */
65	export function useImportRediscovered(jobId: string) {
66	  const queryClient = useQueryClient();
67	
68	  return useMutation<ImportResponse, Error, string[]>({
69	    mutationFn: async (sourceResumeIds: string[]): Promise<ImportResponse> => {
70	      const { data, error } = await supabase.functions.invoke<ImportResponse>(
71	        "import-rediscovered",
72	        { body: { job_id: jobId, source_resume_ids: sourceResumeIds } },
73	      );
74	
75	      if (error) throw error;
76	      if (!data) throw new Error("No response from import function");
77	      return data;
78	    },
79	
80	    onSuccess: (response) => {
81	      toast.success(response.message ?? "Candidates imported");
82	
83	      // Invalidate queries so the job detail view refetches resumes + results
84	      queryClient.invalidateQueries({ queryKey: ["resumes", jobId] });
85	      queryClient.invalidateQueries({ queryKey: ["results", jobId] });
86	      queryClient.invalidateQueries({ queryKey: ["existing-resumes", jobId] });
87	    },
88	
89	    onError: (error) => {
90	      toast.error(`Import failed: ${error.message}`);
91	    },
92	  });
93	}
