1	/**
2	 * send-sequence-step
3	 *
4	 * Cron worker — invoked every 5 minutes via pg_cron or Supabase Dashboard Cron Jobs.
5	 * Picks up to 50 pending sequence_sends whose scheduled_for <= now(),
6	 * renders the step template with candidate variables, sends via Resend, and
7	 * updates send status.
8	 *
9	 * Variable support: {{candidate_name}}, {{job_title}}, {{recruiter_name}},
10	 *                   {{company}}, {{recruiter_email}}
11	 */
12	
13	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
14	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
15	import { logSystemError, errorToMessage } from "../_shared/logError.ts";
16	
17	const BATCH_LIMIT = 50;
18	
19	/** Replace {{variable}} placeholders in a string */
20	function renderTemplate(template: string, vars: Record<string, string>): string {
21	  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => vars[key] ?? "");
22	}
23	
24	/** Send a single email via Resend */
25	async function sendViaResend(
26	  apiKey: string,
27	  from: { email: string; name: string },
28	  to: string,
29	  subject: string,
30	  htmlContent: string
31	): Promise<{ ok: boolean; resendId: string | null; errorMessage: string | null }> {
32	  const res = await fetch("https://api.resend.com/emails", {
33	    method: "POST",
34	    headers: {
35	      Authorization: `Bearer ${apiKey}`,
36	      "Content-Type": "application/json",
37	    },
38	    body: JSON.stringify({
39	      from: `${from.name} <${from.email}>`,
40	      to: [to],
41	      subject,
42	      html: htmlContent,
43	    }),
44	  });
45	
46	  const body = await res.text();
47	
48	  if (!res.ok) {
49	    let errorMessage = `Resend error status=${res.status}`;
50	    try {
51	      const parsed = JSON.parse(body);
52	      errorMessage = parsed.message || parsed.error?.message || errorMessage;
53	    } catch { /* ignore */ }
54	    return { ok: false, resendId: null, errorMessage };
55	  }
56	
57	  let resendId: string | null = null;
58	  try {
59	    const parsed = JSON.parse(body);
60	    resendId = parsed.id ?? null;
61	  } catch { /* ignore */ }
62	
63	  return { ok: true, resendId, errorMessage: null };
64	}
