66	serve(async (req) => {
67	  // Only service-role calls (from cron) are expected — no CORS needed.
68	  // But still allow OPTIONS for safety.
69	  if (req.method === "OPTIONS") {
70	    return new Response(null, {
71	      headers: { "Access-Control-Allow-Headers": "authorization, content-type" },
72	    });
73	  }
74	
75	  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
76	  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
77	
78	  // Allow invocation from cron (service role bearer) or directly with user JWT
79	  const authHeader = req.headers.get("Authorization") ?? "";
80	  const token = authHeader.replace("Bearer ", "");
81	  const expectedServiceToken = SUPABASE_SERVICE_ROLE_KEY;
82	
83	  // Accept either service role key (cron) or any valid bearer — we use service role client throughout
84	  const isCronCall = token === expectedServiceToken;
85	  if (!isCronCall) {
86	    // Allow authenticated calls for manual triggering during development
87	    const supabaseCheck = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
88	    const { error } = await supabaseCheck.auth.getUser(token);
89	    if (error) {
90	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
91	        status: 401,
92	        headers: { "Content-Type": "application/json" },
93	      });
94	    }
95	  }
96	
97	  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
98	
99	  try {
100	    // Load platform config once for all sends in this batch
101	    const { data: config, error: configError } = await supabase
102	      .from("platform_config")
103	      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled")
104	      .limit(1)
105	      .single();
106	
107	    if (configError) throw new Error(`Config error: ${configError.message}`);
108	
109	    if (!config?.outbound_email_enabled || !config.resend_api_key) {
110	      return new Response(
111	        JSON.stringify({ skipped: true, reason: "Email disabled or Resend key missing" }),
112	        { status: 200, headers: { "Content-Type": "application/json" } }
113	      );
114	    }
115	
116	    const fromEmail = config.email_from_address || "noreply@rankora.co";
117	    const fromName = config.email_from_name || "Rankora";
118	
119	    // Fetch pending sends — join all needed data in one query chain
120	    const { data: pendingSends, error: fetchError } = await supabase
121	      .from("sequence_sends")
122	      .select(`
123	        id,
124	        scheduled_for,
125	        enrollment_id,
126	        step_id,
127	        sequence_steps (
128	          subject,
129	          body,
130	          step_order,
131	          sequence_id
132	        ),
133	        sequence_enrollments (
134	          id,
135	          status,
136	          resume_id,
137	          job_id,
138	          enrolled_by,
139	          resumes (
140	            candidate_name,
141	            candidate_email
142	          ),
143	          jobs (
144	            title
145	          ),
146	          profiles:enrolled_by (
147	            full_name,
148	            company_name
149	          )
150	        )
151	      `)
152	      .eq("status", "pending")
153	      .lte("scheduled_for", new Date().toISOString())
154	      .limit(BATCH_LIMIT);
155	
156	    if (fetchError) throw new Error(`Fetch error: ${fetchError.message}`);
157	    if (!pendingSends || pendingSends.length === 0) {
158	      return new Response(
159	        JSON.stringify({ processed: 0, message: "No pending sends" }),
160	        { status: 200, headers: { "Content-Type": "application/json" } }
161	      );
162	    }
163	
164	    let sent = 0;
165	    let failed = 0;
166	    let skipped = 0;
167	
168	    for (const send of pendingSends) {
169	      const enrollment = send.sequence_enrollments as any;
170	      const step = send.sequence_steps as any;
171	
172	      // Skip if enrollment is paused or stopped
173	      if (!enrollment || enrollment.status === "paused" || enrollment.status === "stopped") {
174	        await supabase
175	          .from("sequence_sends")
176	          .update({ status: "skipped", error: `Enrollment ${enrollment?.status ?? "missing"}` })
177	          .eq("id", send.id);
178	        skipped++;
179	        continue;
180	      }
181	
182	      const resume = enrollment.resumes as any;
183	      const candidateEmail = resume?.candidate_email;
184	
185	      if (!candidateEmail) {
186	        await supabase
187	          .from("sequence_sends")
188	          .update({ status: "skipped", error: "No candidate email" })
189	          .eq("id", send.id);
190	        skipped++;
191	        continue;
192	      }
193	
194	      // Build template variables
195	      const recruiterProfile = enrollment.profiles as any;
196	      const variables: Record<string, string> = {
197	        candidate_name: resume?.candidate_name || "Candidate",
198	        job_title: enrollment.jobs?.title || "the position",
199	        recruiter_name: recruiterProfile?.full_name || fromName,
200	        company: recruiterProfile?.company_name || fromName,
201	        recruiter_email: fromEmail,
202	      };
203	
204	      const subject = renderTemplate(step.subject, variables);
205	      // Convert newlines to <br> for HTML email, then render variables
206	      const bodyHtml = renderTemplate(
207	        step.body.replace(/\n/g, "<br>"),
208	        variables
209	      );
210	
211	      try {
212	        const result = await sendViaResend(
213	          config.resend_api_key,
214	          { email: fromEmail, name: variables.recruiter_name || fromName },
215	          candidateEmail,
216	          subject,
217	          bodyHtml
218	        );
219	
220	        if (result.ok) {
221	          await supabase
222	            .from("sequence_sends")
223	            .update({
224	              status: "sent",
225	              sent_at: new Date().toISOString(),
226	              resend_id: result.resendId,
227	              error: null,
228	            })
229	            .eq("id", send.id);
230	          sent++;
231	        } else {
232	          await supabase
233	            .from("sequence_sends")
234	            .update({ status: "failed", error: result.errorMessage })
235	            .eq("id", send.id);
236	          failed++;
237	
238	          await logSystemError({
239	            function_name: "send-sequence-step",
240	            error_type: "RESEND_ERROR",
241	            severity: "warning",
242	            error_message: result.errorMessage ?? "Unknown Resend error",
243	            user_id: enrollment.enrolled_by,
244	          });
245	        }
246	      } catch (sendErr: unknown) {
247	        const msg = errorToMessage(sendErr);
248	        await supabase
249	          .from("sequence_sends")
250	          .update({ status: "failed", error: msg })
251	          .eq("id", send.id);
252	        failed++;
253	        console.error(`send-sequence-step send error for send ${send.id}:`, msg);
254	      }
255	    }
256	
257	    // Mark completed enrollments (all sends done)
258	    // Find enrollments where all sends are no longer pending
259	    const enrollmentIds = [...new Set(pendingSends.map((s) => s.enrollment_id))];
260	    for (const enrollmentId of enrollmentIds) {
261	      const { count } = await supabase
262	        .from("sequence_sends")
263	        .select("*", { count: "exact", head: true })
264	        .eq("enrollment_id", enrollmentId)
265	        .eq("status", "pending");
266	
267	      if ((count ?? 0) === 0) {
268	        await supabase
269	          .from("sequence_enrollments")
270	          .update({ status: "completed", completed_at: new Date().toISOString() })
271	          .eq("id", enrollmentId)
272	          .eq("status", "active");
273	      }
274	    }
275	
276	    return new Response(
277	      JSON.stringify({ processed: pendingSends.length, sent, failed, skipped }),
278	      { status: 200, headers: { "Content-Type": "application/json" } }
279	    );
280	  } catch (err: unknown) {
281	    console.error("send-sequence-step error:", err);
282	    await logSystemError({
283	      function_name: "send-sequence-step",
284	      error_type: "CRON_ERROR",
285	      severity: "error",
286	      error_message: errorToMessage(err),
287	    });
288	    return new Response(
289	      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
290	      { status: 500, headers: { "Content-Type": "application/json" } }
291	    );
292	  }
293	});
