1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
3	import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
4	
5	const ALLOWED_ORIGINS = [
6	  "https://rankora.co",
7	  "https://www.rankora.co",
8	  "http://localhost:8080",
9	  "http://localhost:5173",
10	];
11	
12	function getCorsOrigin(req: Request): string {
13	  const origin = req.headers.get("origin") || "";
14	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
15	}
16	
17	interface EnrollRequest {
18	  sequence_id: string;
19	  resume_ids: string[];
20	  job_id: string;
21	}
22	
23	interface SequenceStep {
24	  id: string;
25	  day_offset: number;
26	  step_order: number;
27	  subject: string;
28	  body: string;
29	}
30	
31	serve(async (req) => {
32	  const corsHeaders = {
33	    "Access-Control-Allow-Origin": getCorsOrigin(req),
34	    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
35	  };
36	
37	  if (req.method === "OPTIONS") {
38	    return new Response(null, { headers: corsHeaders });
39	  }
40	
41	  if (req.method !== "POST") {
42	    return new Response(JSON.stringify({ error: "Method not allowed" }), {
43	      status: 405,
44	      headers: { ...corsHeaders, "Content-Type": "application/json" },
45	    });
46	  }
47	
48	  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
49	  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
50	  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
51	
52	  // Verify JWT
53	  const authHeader = req.headers.get("Authorization");
54	  if (!authHeader) {
55	    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
56	      status: 401,
57	      headers: { ...corsHeaders, "Content-Type": "application/json" },
58	    });
59	  }
60	
61	  const token = authHeader.replace("Bearer ", "");
62	  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
63	  if (authError || !user) {
64	    return new Response(JSON.stringify({ error: "Unauthorized" }), {
65	      status: 401,
66	      headers: { ...corsHeaders, "Content-Type": "application/json" },
67	    });
68	  }
69	
70	  try {
71	    const { sequence_id, resume_ids, job_id } = (await req.json()) as EnrollRequest;
72	
73	    if (!sequence_id || !Array.isArray(resume_ids) || resume_ids.length === 0 || !job_id) {
74	      return new Response(
75	        JSON.stringify({ error: "Missing required fields: sequence_id, resume_ids, job_id" }),
76	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
77	      );
78	    }
79	
80	    // Verify the sequence exists and is owned by or shared with the requesting user
81	    const { data: sequence, error: seqError } = await supabase
82	      .from("sequences")
83	      .select("id, is_active, user_id, team_id")
84	      .eq("id", sequence_id)
85	      .single();
86	
87	    if (seqError || !sequence) {
88	      return new Response(JSON.stringify({ error: "Sequence not found" }), {
89	        status: 404,
90	        headers: { ...corsHeaders, "Content-Type": "application/json" },
91	      });
92	    }
93	
94	    if (!sequence.is_active) {
95	      return new Response(JSON.stringify({ error: "Sequence is inactive" }), {
96	        status: 400,
97	        headers: { ...corsHeaders, "Content-Type": "application/json" },
98	      });
99	    }
100	
101	    // Verify ownership / team membership
102	    let hasAccess = sequence.user_id === user.id;
103	    if (!hasAccess && sequence.team_id) {
104	      const { count } = await supabase
105	        .from("team_members")
106	        .select("*", { count: "exact", head: true })
107	        .eq("team_id", sequence.team_id)
108	        .eq("user_id", user.id);
109	      hasAccess = (count ?? 0) > 0;
110	    }
111	
112	    if (!hasAccess) {
113	      return new Response(JSON.stringify({ error: "Forbidden" }), {
114	        status: 403,
115	        headers: { ...corsHeaders, "Content-Type": "application/json" },
116	      });
117	    }
118	
119	    // Fetch all steps for this sequence
120	    const { data: steps, error: stepsError } = await supabase
121	      .from("sequence_steps")
122	      .select("id, day_offset, step_order, subject, body")
123	      .eq("sequence_id", sequence_id)
124	      .order("step_order", { ascending: true });
125	
