/**
 * unsubscribe
 *
 * Public GET endpoint — no auth required.
 * Accepts ?token=<base64url(email:HMAC-SHA256)> query param.
 * Verifies the HMAC signature, inserts the email into email_unsubscribes,
 * and returns a plain HTML confirmation page.
 *
 * Token format: base64url(email + ":" + hex(HMAC-SHA256(email, UNSUBSCRIBE_SECRET)))
 */

import { createClient } from "jsr:@supabase/supabase-js@2";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const UNSUBSCRIBE_SECRET = Deno.env.get("UNSUBSCRIBE_SECRET") || "";

async function verifyToken(token: string): Promise<string | null> {
  try {
    const decoded = atob(token.replace(/-/g, "+").replace(/_/g, "/"));
    const separatorIdx = decoded.lastIndexOf(":");
    if (separatorIdx === -1) return null;

    const email = decoded.substring(0, separatorIdx);
    const providedHex = decoded.substring(separatorIdx + 1);

    if (!email || !providedHex) return null;

    // Compute HMAC-SHA256 over the email
    const keyData = new TextEncoder().encode(UNSUBSCRIBE_SECRET);
    const msgData = new TextEncoder().encode(email);
    const key = await crypto.subtle.importKey(
      "raw",
      keyData,
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"],
    );
    const signature = await crypto.subtle.sign("HMAC", key, msgData);
    const expectedHex = Array.from(new Uint8Array(signature))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("");

    if (expectedHex !== providedHex) return null;
    return email;
  } catch {
    return null;
  }
}

function htmlPage(title: string, body: string): Response {
  return new Response(
    `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${title} — Rankora</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; display: flex; align-items: center; justify-content: center; min-height: 100vh; margin: 0; background: #f9fafb; color: #111827; }
    .card { background: white; border-radius: 12px; padding: 40px; max-width: 480px; text-align: center; box-shadow: 0 1px 3px rgba(0,0,0,.1); }
    h1 { font-size: 1.5rem; margin-bottom: 12px; }
    p { color: #6b7280; line-height: 1.6; }
    a { color: #6366f1; text-decoration: none; }
  </style>
</head>
<body>
  <div class="card">
    <h1>${title}</h1>
    ${body}
  </div>
</body>
</html>`,
    {
      status: 200,
      headers: { "Content-Type": "text/html; charset=utf-8" },
    },
  );
}

Deno.serve(async (req) => {
  // Only GET (user clicks email link) and OPTIONS (CORS preflight)
  if (req.method === "OPTIONS") {
    return new Response(null, {
      headers: { "Access-Control-Allow-Headers": "content-type" },
    });
  }

  if (req.method !== "GET") {
    return new Response("Method not allowed", { status: 405 });
  }

  const url = new URL(req.url);
  const token = url.searchParams.get("token");

  if (!token) {
    return htmlPage(
      "Invalid unsubscribe link",
      "<p>This unsubscribe link is invalid or has expired. Please contact support if you continue to receive emails.</p>",
    );
  }

  if (!UNSUBSCRIBE_SECRET) {
    console.error("UNSUBSCRIBE_SECRET env var not set");
    return htmlPage(
      "Configuration error",
      "<p>We encountered an issue processing your request. Please contact <a href='mailto:support@rankora.co'>support@rankora.co</a> to unsubscribe.</p>",
    );
  }

  const email = await verifyToken(token);
  if (!email) {
    return htmlPage(
      "Invalid unsubscribe link",
      "<p>This unsubscribe link is invalid or expired. Please contact <a href='mailto:support@rankora.co'>support@rankora.co</a> to unsubscribe manually.</p>",
    );
  }

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Upsert — idempotent, safe to click multiple times
  const { error } = await supabase
    .from("email_unsubscribes")
    .upsert({ email: email.toLowerCase().trim(), source: "sequence" }, { onConflict: "email" });

  if (error) {
    console.error("Failed to record unsubscribe:", error);
    return htmlPage(
      "Error processing request",
      "<p>We encountered an issue recording your request. Please contact <a href='mailto:support@rankora.co'>support@rankora.co</a> and we'll remove you immediately.</p>",
    );
  }

  return htmlPage(
    "You've been unsubscribed",
    `<p>The email address <strong>${email}</strong> has been removed from all recruitment sequences.</p>
     <p style="margin-top:16px">You will no longer receive automated emails from Rankora recruitment sequences. If you believe this was a mistake, please reply to any recent email.</p>`,
  );
});

/**
 * Shared utility: generate HMAC-SHA256 unsubscribe tokens.
 * Token format: base64url(email + ":" + hex(HMAC-SHA256(email, secret)))
 * Used by send-sequence-step to embed unsubscribe links in every email.
 */

export async function generateUnsubscribeToken(email: string, secret: string): Promise<string> {
  const keyData = new TextEncoder().encode(secret);
  const msgData = new TextEncoder().encode(email);
  const key = await crypto.subtle.importKey(
    "raw",
    keyData,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", key, msgData);
  const hex = Array.from(new Uint8Array(signature))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
  const raw = `${email}:${hex}`;
  // base64url encode (URL-safe, no padding)
  return btoa(raw).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export async function buildUnsubscribeUrl(
  email: string,
  secret: string,
  supabaseUrl: string,
): Promise<string> {
  const token = await generateUnsubscribeToken(email, secret);
  return `${supabaseUrl}/functions/v1/unsubscribe?token=${encodeURIComponent(token)}`;
}

/**
 * send-sequence-step
 *
 * Cron worker — invoked every 5 minutes via pg_cron or Supabase Dashboard Cron Jobs.
 * Picks up to 50 pending sequence_sends whose scheduled_for <= now(),
 * renders the step template with candidate variables, sends via Resend, and
 * updates send status.
 *
 * Variable support: {{candidate_name}}, {{job_title}}, {{recruiter_name}},
 *                   {{company}}, {{recruiter_email}}
 *
 * Security: accepts ONLY service-role key (Fix C2).
 * Compliance: checks email_unsubscribes before sending, appends unsubscribe footer (Fix C3).
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage } from "../_shared/logError.ts";
import { buildUnsubscribeUrl } from "../_shared/unsubscribeToken.ts";

const BATCH_LIMIT = 50;
const PARALLEL_CHUNK_SIZE = 5; // Fix H2: send 5 in parallel, then next chunk

// Fix M2: Escape HTML to prevent injection via user-controlled template variables
function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }[c]!));
}

/** Replace {{variable}} placeholders in a string (values pre-escaped) */
function renderTemplate(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => vars[key] ?? "");
}

/** Send a single email via Resend */
async function sendViaResend(
  apiKey: string,
  from: { email: string; name: string },
  to: string,
  subject: string,
  htmlContent: string,
): Promise<{ ok: boolean; resendId: string | null; errorMessage: string | null }> {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: `${from.name} <${from.email}>`,
      to: [to],
      subject,
      html: htmlContent,
    }),
  });

  const body = await res.text();

  if (!res.ok) {
    let errorMessage = `Resend error status=${res.status}`;
    try {
      const parsed = JSON.parse(body);
      errorMessage = parsed.message || parsed.error?.message || errorMessage;
    } catch { /* ignore */ }
    return { ok: false, resendId: null, errorMessage };
  }

  let resendId: string | null = null;
  try {
    const parsed = JSON.parse(body);
    resendId = parsed.id ?? null;
  } catch { /* ignore */ }

  return { ok: true, resendId, errorMessage: null };
}

// ── Typed shapes for Supabase joined query ───────────────────────────────────

interface SequenceStep {
  subject: string;
  body: string;
  step_order: number;
  sequence_id: string;
}

interface ResumeRow {
  candidate_name: string | null;
  candidate_email: string | null;
}

interface JobRow {
  title: string | null;
}

interface ProfileRow {
  full_name: string | null;
  company_name: string | null;
}

interface EnrollmentRow {
  id: string;
  status: string;
  resume_id: string;
  job_id: string;
  enrolled_by: string;
  resumes: ResumeRow | null;
  jobs: JobRow | null;
  profiles: ProfileRow | null;
}

interface PendingSend {
  id: string;
  scheduled_for: string;
  enrollment_id: string;
  step_id: string;
  sequence_steps: SequenceStep | null;
  sequence_enrollments: EnrollmentRow | null;
}

serve(async (req) => {
  // Only service-role calls (from cron) are expected — no CORS needed.
  if (req.method === "OPTIONS") {
    return new Response(null, {
      headers: { "Access-Control-Allow-Headers": "authorization, content-type" },
    });
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const UNSUBSCRIBE_SECRET = Deno.env.get("UNSUBSCRIBE_SECRET") || "";

  // Fix C2: Accept ONLY service-role key — no dev-mode user fallback.
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace("Bearer ", "");
  if (token !== SUPABASE_SERVICE_ROLE_KEY) {
    return new Response(JSON.stringify({ error: "Forbidden: service role required" }), {
      status: 403,
      headers: { "Content-Type": "application/json" },
    });
  }

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    // Load platform config once for all sends in this batch
    const { data: config, error: configError } = await supabase
      .from("platform_config")
      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled")
      .limit(1)
      .single();

    if (configError) throw new Error(`Config error: ${configError.message}`);

    if (!config?.outbound_email_enabled || !config.resend_api_key) {
      return new Response(
        JSON.stringify({ skipped: true, reason: "Email disabled or Resend key missing" }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }

    const fromEmail = config.email_from_address || "noreply@rankora.co";
    const fromName = config.email_from_name || "Rankora";

    // Fetch pending sends — join all needed data in one query chain
    // Fix H1: type response properly instead of casting to `any`
    const { data: rawPendingSends, error: fetchError } = await supabase
      .from("sequence_sends")
      .select(`
        id,
        scheduled_for,
        enrollment_id,
        step_id,
        sequence_steps (
          subject,
          body,
          step_order,
          sequence_id
        ),
        sequence_enrollments (
          id,
          status,
          resume_id,
          job_id,
          enrolled_by,
          resumes (
            candidate_name,
            candidate_email
          ),
          jobs (
            title
          ),
          profiles:enrolled_by (
            full_name,
            company_name
          )
        )
      `)
      .eq("status", "pending")
      .lte("scheduled_for", new Date().toISOString())
      .limit(BATCH_LIMIT);

    if (fetchError) throw new Error(`Fetch error: ${fetchError.message}`);
    if (!rawPendingSends || rawPendingSends.length === 0) {
      return new Response(
        JSON.stringify({ processed: 0, message: "No pending sends" }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      );
    }

    // Fix H1: Supabase returns single-row FK joins as objects (not arrays) for NOT NULL FKs.
    // Cast via unknown to our typed interface rather than using `any`.
    const pendingSends = rawPendingSends as unknown as PendingSend[];

    let sent = 0;
    let failed = 0;
    let skipped = 0;

    // Fix H2: Process in parallel chunks of PARALLEL_CHUNK_SIZE
    for (let i = 0; i < pendingSends.length; i += PARALLEL_CHUNK_SIZE) {
      const chunk = pendingSends.slice(i, i + PARALLEL_CHUNK_SIZE);

      await Promise.allSettled(
        chunk.map(async (send) => {
          const enrollment = send.sequence_enrollments;
          const step = send.sequence_steps;

          // Skip if enrollment is paused or stopped
          if (!enrollment || enrollment.status === "paused" || enrollment.status === "stopped") {
            await supabase
              .from("sequence_sends")
              .update({
                status: "skipped",
                error: `Enrollment ${enrollment?.status ?? "missing"}`,
              })
              .eq("id", send.id);
            skipped++;
            return;
          }

          const resume = enrollment.resumes;
          const candidateEmail = resume?.candidate_email;

          if (!candidateEmail) {
            await supabase
              .from("sequence_sends")
              .update({ status: "skipped", error: "No candidate email" })
              .eq("id", send.id);
            skipped++;
            return;
          }

          // Fix C3: Check unsubscribe list before sending
          const { data: unsubRow } = await supabase
            .from("email_unsubscribes")
            .select("email")
            .eq("email", candidateEmail.toLowerCase().trim())
            .maybeSingle();

          if (unsubRow) {
            await supabase
              .from("sequence_sends")
              .update({ status: "skipped", error: "unsubscribed" })
              .eq("id", send.id);
            skipped++;
            return;
          }

          if (!step) {
            await supabase
              .from("sequence_sends")
              .update({ status: "skipped", error: "Step not found" })
              .eq("id", send.id);
            skipped++;
            return;
          }

          // Build template variables — Fix M2: escape user-controlled values
          const recruiterProfile = enrollment.profiles;
          const recruiterName = escapeHtml(recruiterProfile?.full_name || fromName);
          const variables: Record<string, string> = {
            candidate_name: escapeHtml(resume?.candidate_name || "Candidate"),
            job_title: escapeHtml(enrollment.jobs?.title || "the position"),
            recruiter_name: recruiterName,
            company: escapeHtml(recruiterProfile?.company_name || fromName),
            recruiter_email: escapeHtml(fromEmail),
          };

          const subject = renderTemplate(step.subject, variables);
          // Convert newlines to <br> for HTML email, then render variables
          const bodyHtml = renderTemplate(
            step.body.replace(/\n/g, "<br>"),
            variables,
          );

          // Fix C3: Generate unsubscribe URL and append mandatory footer
          let unsubscribeUrl = "https://rankora.co";
          if (UNSUBSCRIBE_SECRET) {
            try {
              unsubscribeUrl = await buildUnsubscribeUrl(
                candidateEmail,
                UNSUBSCRIBE_SECRET,
                SUPABASE_URL,
              );
            } catch (e) {
              console.error("Failed to generate unsubscribe URL:", e);
            }
          }

          const unsubscribeFooter = `
<br><br>
<hr style="border:none;border-top:1px solid #e5e7eb;margin:16px 0">
<p style="font-size:12px;color:#9ca3af;margin:0">
  This email was sent by ${recruiterName} via <a href="https://rankora.co" style="color:#9ca3af">Rankora</a>.<br>
  To stop receiving these messages, <a href="${unsubscribeUrl}" style="color:#9ca3af">unsubscribe here</a>.
</p>`;

          const finalHtml = bodyHtml + unsubscribeFooter;

          try {
            const result = await sendViaResend(
              config.resend_api_key,
              { email: fromEmail, name: variables.recruiter_name || fromName },
              candidateEmail,
              subject,
              finalHtml,
            );

            if (result.ok) {
              await supabase
                .from("sequence_sends")
                .update({
                  status: "sent",
                  sent_at: new Date().toISOString(),
                  resend_id: result.resendId,
                  error: null,
                })
                .eq("id", send.id);
              sent++;
            } else {
              await supabase
                .from("sequence_sends")
                .update({ status: "failed", error: result.errorMessage })
                .eq("id", send.id);
              failed++;

              await logSystemError({
                function_name: "send-sequence-step",
                error_type: "RESEND_ERROR",
                severity: "warning",
                error_message: result.errorMessage ?? "Unknown Resend error",
                user_id: enrollment.enrolled_by,
              });
            }
          } catch (sendErr: unknown) {
            const msg = errorToMessage(sendErr);
            await supabase
              .from("sequence_sends")
              .update({ status: "failed", error: msg })
              .eq("id", send.id);
            failed++;
            console.error(`send-sequence-step send error for send ${send.id}:`, msg);
          }
        }),
      );

      // Small delay between chunks to avoid Resend rate limits
      if (i + PARALLEL_CHUNK_SIZE < pendingSends.length) {
        await new Promise((resolve) => setTimeout(resolve, 200));
      }
    }

    // Mark completed enrollments (all sends done)
    const enrollmentIds = [...new Set(pendingSends.map((s) => s.enrollment_id))];
    for (const enrollmentId of enrollmentIds) {
      const { count } = await supabase
        .from("sequence_sends")
        .select("*", { count: "exact", head: true })
        .eq("enrollment_id", enrollmentId)
        .eq("status", "pending");

      if ((count ?? 0) === 0) {
        await supabase
          .from("sequence_enrollments")
          .update({ status: "completed", completed_at: new Date().toISOString() })
          .eq("id", enrollmentId)
          .eq("status", "active");
      }
    }

    return new Response(
      JSON.stringify({ processed: pendingSends.length, sent, failed, skipped }),
      { status: 200, headers: { "Content-Type": "application/json" } },
    );
  } catch (err: unknown) {
    console.error("send-sequence-step error:", err);
    await logSystemError({
      function_name: "send-sequence-step",
      error_type: "CRON_ERROR",
      severity: "error",
      error_message: errorToMessage(err),
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { "Content-Type": "application/json" } },
    );
  }
});

